module ArmTop(
	sys_clk,
	rst_n,
	AM1,
	AM2,
	AM3,
	AM4,
	AM5,
	AM6,
	u_txd,
	tcon);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input [15:0] AM1;
	input [15:0] AM2;
	input [15:0] AM3;
	input [15:0] AM4;
	input [15:0] AM5;
	input [15:0] AM6;
	output u_txd;
	output tcon;

	wire sys_clk;
	wire rst_n;
	wire [15:0] AM1;
	wire [15:0] AM2;
	wire [15:0] AM3;
	wire [15:0] AM4;
	wire [15:0] AM5;
	wire [15:0] AM6;
	wire u_txd;
	wire tcon;

	//----Code starts here: integrated by Robei-----
	    parameter  DATA_time=16'd100;
		parameter CNT_1s=5;             //正常为33333，便于仿真，这里设置为5
		wire [3:0] arm_cmd;
		reg [25:0] cnt_1s;
		wire [7:0]  data_ID;
		wire new_cmd_flag;
		wire [15:0] data_angle;
		wire [15:0] data_time;
		reg  start;
	    wire uart_ten_busy;
		reg  uart_ten_busy_reg;
		wire busy_neg;
		wire busy_pos;
		wire[7:0]data_send;
		reg [7:0]  data_ID_reg;    
		reg [15:0] data_angle_reg;
		reg [15:0] data_time_reg; 
		wire[3:0]  length_cycle;
		reg [3:0]  cnt_cycle;
		reg [3:0]  cmd_reg;
		reg new_cmd_flag_d1;
		reg new_cmd_flag_d2;
		wire new_cmd_flag_rise;
		
	    assign data_ID = data_ID_reg;     
		assign data_angle= data_angle_reg;
		assign data_time = data_time_reg; 
		assign tcon=1'b1;
		assign length_cycle=4'd6;
		assign busy_neg=~uart_ten_busy&&uart_ten_busy_reg;
		assign busy_pos=uart_ten_busy&&~uart_ten_busy_reg;
		
		always @(posedge sys_clk or negedge rst_n)begin
		 	if(!rst_n) begin
		 		new_cmd_flag_d1 <= 1'd0;
		 		new_cmd_flag_d2 <= 1'd0;
		 	end
		 	else begin
		 		new_cmd_flag_d1 <= new_cmd_flag;
		 		new_cmd_flag_d2 <= new_cmd_flag_d1;
		 	end
		 end
		 
		 assign new_cmd_flag_rise = ~new_cmd_flag_d2 && new_cmd_flag_d1;
		
		//reg 
		always @(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)begin
		        uart_ten_busy_reg<=1'b0;
		        cmd_reg<=4'b0000;
		    end
		    else begin
		        uart_ten_busy_reg<=uart_ten_busy;
		        cmd_reg<= arm_cmd;
		    end   
		end
		//cnt_1s
		always @(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)
		        cnt_1s<=26'd0;
		    else if(~uart_ten_busy)
		        if(cnt_1s<CNT_1s)
		            cnt_1s<=cnt_1s+1;
		        else if(cnt_cycle<length_cycle)
		            cnt_1s<=cnt_1s;
		        else
		            cnt_1s<=26'd0;
		    else
		        cnt_1s<=26'd0;
		end
		//start
		always @(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)
		        start<=1'b0;
		    else if(busy_pos)
		        start<=1'b0;
		    else if(cnt_1s==CNT_1s-1&&cnt_cycle<length_cycle)
		        start<=1'b1;
		    else
		        start<=start;        
		end
		//cnt_cycle
		always @(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)
		        cnt_cycle<=4'b0000;
		    else if(busy_neg)
		        cnt_cycle<=cnt_cycle+1;
		    else if(new_cmd_flag_rise)
		        cnt_cycle<=4'b0000;
		    else
		        cnt_cycle<=cnt_cycle;
		end
		
	   always @(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)begin
		        data_ID_reg<=8'd0;   
		        data_angle_reg<=16'd0;
		        data_time_reg<=16'd0;
		     end
		     else begin
		         data_time_reg<= DATA_time;
		         case(cnt_cycle)
		             4'd0:begin                      
		                 data_ID_reg <=  8'd6;      
		                 data_angle_reg	<= AM6;  
		             end                             
		             4'd1:begin                      
		                 data_ID_reg <=  8'd5;      
		                 data_angle_reg	<= AM5;
		             end
		             4'd2:begin                      
		                 data_ID_reg <=  8'd4;      
		                 data_angle_reg	<= AM4;
		             end
		             4'd3:begin                      
		                 data_ID_reg <=  8'd3;      
		                 data_angle_reg	<= AM3;  
		             end
		             4'd4:begin                      
		                 data_ID_reg <=  8'd2;      
		                 data_angle_reg	<= AM2;
		             end
		             4'd5:begin                      
		                 data_ID_reg <=  8'd1;      
		                 data_angle_reg	<= AM1;
		             end
		             default:;
		         endcase
		     end
	end
	
	
	//---Module instantiation---
	uart_ten uart_ten1(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.data_ID(data_ID),
		.data_angle(data_angle),
		.data_time(data_time),
		.start(start),
		.uart_ten_busy(uart_ten_busy),
		.u_txd(u_txd),
		.uart_en(uart_en),
		.data_send(data_send));

endmodule    //ArmTop

